import sys
from collections import defaultdict

def normalize(word):
    return ''.join(c.lower() for c in word if c.isalpha())

def generate_variants(word):
    variants = set()

    # Deletion
    for i in range(len(word)):
        variants.add(word[:i] + word[i+1:])

    # Insertion
    for i in range(len(word) + 1):
        for c in 'abcdefghijklmnopqrstuvwxyz':
            variants.add(word[:i] + c + word[i:])

    # Replacement
    for i in range(len(word)):
        for c in 'abcdefghijklmnopqrstuvwxyz':
            if c != word[i]:
                variants.add(word[:i] + c + word[i+1:])

    # Transposition
    for i in range(len(word) - 1):
        variants.add(word[:i] + word[i+1] + word[i] + word[i+2:])

    return variants

def main():
    text = []
    for line in sys.stdin:
        if line.strip() == "***":
            break
        text.append(line)

    words = []
    for line in text:
        words.extend(normalize(word) for word in line.split())

    word_to_variants = defaultdict(set)
    for word in words:
        for variant in generate_variants(word):
            word_to_variants[variant].add(word)

    result = {}
    for word, variants in word_to_variants.items():
        if len(variants) > 1:
            result[word] = sorted(variants - {word})

    if not result:
        print("***")
    else:
        for word in sorted(result.keys()):
            print(f"{word}: {' '.join(result[word])}")

if __name__ == "__main__":
    main()
