    def delete_char(word):
        return [word[:i] + word[i+1:] for i in range(len(word))]

    def insert_char(word):
        return [word[:i] + c + word[i:] for i in range(len(word) + 1) for c in 'abcdefghijklmnopqrstuvwxyz']

    def replace_char(word):
        return [word[:i] + c + word[i+1:] for i in range(len(word)) for c in 'abcdefghijklmnopqrstuvwxyz' if c != word[i]]

    def transpose_chars(word):
        return [word[:i] + word[i+1] + word[i] + word[i+2:] for i in range(len(word) - 1)]

    similar_words = set()
    similar_words.update(delete_char(word))
    similar_words.update(insert_char(word))
