        # Check for replace or transpose
        diff_count = sum(c1 != c2 for c1, c2 in zip(word1, word2))
        if diff_count == 1:
            return True
        # Check for transpose
        for i in range(len(word1) - 1):
            if word1[i] == word2[i+1] and word1[i+1] == word2[i]:
                return True
    elif len(word1) + 1 == len(word2):
